VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.39,"Lecture twelve. Virtualisation and containers. How to ship the whole kitchen along with the recipe."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":28.352,"caps":[[0.5,6.27,"Mo's forecaster: forecast.py, the same file on both machines."],[6.52,14.61,"But Windows 11 against Ubuntu, Python 3.12 against 3.8."],[14.86,18.55,"It runs on the laptop and crashes on the server."],[18.8,26.89,"The environment differs: OS, libraries, dependencies, settings."]],"warp":[[0,0],[0.5,0.4],[6.52,3.2],[14.86,5.2],[18.8,7.8],[28.352,12]]},{"dur":21.664,"caps":[[0.5,6.27,"Development, test, production: three machines that start out alike."],[6.52,9.89,"Each gets its own updates and tweaks."],[10.14,15.03,"They drift apart, so deploying across them is fragile."],[15.28,20.33,"The big idea: pack the environment along with the code."]],"warp":[[0,0],[0.5,0.4],[6.52,3],[10.14,5.4],[15.28,7.8],[21.664,12]]},{"dur":25.008,"caps":[[0.5,4.11,"The real computer is the host."],[4.36,10.77,"Each virtual machine is a guest with its own OS."],[11.02,17.43,"The hypervisor shares the host's CPU, memory and disk between them."],[17.68,23.61,"For example VMware Workstation, VirtualBox and Hyper-V."]],"warp":[[0,0],[0.5,0.4],[4.36,2.4],[11.02,5.6],[17.68,9.2],[25.008,13]]},{"dur":21.78,"caps":[[0.5,5.55,"An emulator mimics other hardware, like an old console."],[5.8,11.17,"Every instruction is translated; the game never touches the real hardware."],[11.42,17.03,"A virtual machine does use the host hardware."],[17.28,20.41,"The hypervisor keeps the guests apart."]],"warp":[[0,0],[0.5,0.4],[5.8,2.4],[11.42,5.4],[17.28,9],[21.78,11]]},{"dur":19.876,"caps":[[0.5,5.39,"A snapshot saves the VM's state at one exact moment."],[5.64,9.65,"Then an update is installed, and the forecaster breaks."],[9.9,14.23,"Restore the snapshot: every later change is undone."],[14.48,18.17,"Snapshots can also be copied to another host."]],"warp":[[0,0],[0.5,0.4],[5.64,3.4],[9.9,6.8],[14.48,9],[19.876,11]]},{"dur":30,"caps":[[0.5,5.71,"Three services, three virtual machines."],[5.96,11.57,"Every VM repeats a whole OS: lots of overhead."],[11.82,18.15,"Containers share the host's OS kernel instead."],[18.4,22.89,"Rough numbers: 4 operating systems against 1."],[23.14,29.07,"A container starts in milliseconds, a VM in about a minute."]],"warp":[[0,0],[0.5,0.4],[5.96,2.4],[11.82,5.2],[18.4,7.4],[23.14,10.6],[30,14]]},{"dur":30.001,"caps":[[0.5,6.91,"Docker packs the app with all its dependencies."],[7.16,14.45,"Namespaces: each container sees its own files, network and processes."],[14.7,20.15,"Cgroups: limits on CPU, memory and IO."],[20.4,28.41,"On Windows, Docker Desktop runs a small Linux VM via WSL2 or Hyper-V."]],"warp":[[0,0],[0.5,0.4],[7.16,3.2],[14.7,6.4],[20.4,9.6],[30.001,14]]},{"dur":31.672,"caps":[[0.5,6.59,"One image, three running containers."],[6.84,13.81,"A Dockerfile builds the image line by line, one layer each."],[14.06,18.07,"First build: every layer is made and cached."],[18.32,24.89,"Change only your code: 1 layer rebuilt, 3 from cache."],[25.14,29.79,"Change the library list: rebuilt from that line down."]],"warp":[[0,0],[0.5,0.4],[6.84,3],[14.06,5.6],[18.32,7.8],[25.14,10.8],[31.672,14]]},{"dur":30.418,"caps":[[0.5,6.91,"A cluster: a control plane and worker nodes."],[7.16,13.09,"A Deployment wants 3 pods; a Service gives them one address."],[13.34,16.23,"A pod crashes: it is restarted."],[16.48,22.25,"Node 2 goes down: its pod is rescheduled. Still 3 running."],[22.5,28.83,"Scaling, self-healing, declarative, cloud-native."]],"warp":[[0,0],[0.5,0.4],[7.16,2.6],[13.34,6],[16.48,8.8],[22.5,12],[30.418,15]]},{"dur":18.32,"caps":[],"warp":[[0,0],[0.5,0.9],[6.28,2],[11.34,3.1],[18.32,9]]}]};
